"use client"

import { FindYourTwin } from "@/components/find-your-twin"
import { getOrCreateAnonymousId } from "@/lib/anonymous-id"
import { createClient } from "@/lib/supabase/client"
import { AnimatePresence, motion } from "framer-motion"
import { ArrowLeft, Heart, Loader2, Send } from "lucide-react"
import Link from "next/link"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"

interface EchoAnswer {
  id: string
  anonymous_id: string
  answer_text: string
  question_date: string
  question_text: string
  resonance_count: number
  created_at: string
}

export function EchoesWall() {
  const [anonymousId, setAnonymousId] = useState("")
  const [question, setQuestion] = useState("")
  const [questionDate, setQuestionDate] = useState("")
  const [answers, setAnswers] = useState<EchoAnswer[]>([])
  const [answerText, setAnswerText] = useState("")
  const [postedAnswer, setPostedAnswer] = useState<EchoAnswer | null>(null)
  const [toast, setToast] = useState("")
  const [isLoading, setIsLoading] = useState(true)
  const [isPosting, setIsPosting] = useState(false)
  const previousOwnCounts = useRef<Record<string, number>>({})

  const supabase = useMemo(() => createClient(), [])

  const loadEchoes = useCallback(async () => {
    const response = await fetch("/api/echoes")
    const data = await response.json()

    if (response.ok) {
      setQuestion(data.question)
      setQuestionDate(data.questionDate)
      setAnswers(data.answers || [])
    } else {
      setToast(data.error || "Echoes are quiet right now.")
    }

    setIsLoading(false)
  }, [])

  useEffect(() => {
    const id = getOrCreateAnonymousId()
    setAnonymousId(id)
    loadEchoes()
  }, [loadEchoes])

  useEffect(() => {
    if (!questionDate || !anonymousId) return

    const channel = supabase
      .channel(`echoes:${questionDate}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "echo_answers",
          filter: `question_date=eq.${questionDate}`,
        },
        (payload) => {
          const newAnswer = payload.new as EchoAnswer
          setAnswers((current) => {
            if (current.some((answer) => answer.id === newAnswer.id)) return current
            return [newAnswer, ...current].slice(0, 80)
          })
        }
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "echo_answers",
          filter: `question_date=eq.${questionDate}`,
        },
        (payload) => {
          const updatedAnswer = payload.new as EchoAnswer
          setAnswers((current) =>
            current.map((answer) => (answer.id === updatedAnswer.id ? updatedAnswer : answer))
          )

          if (updatedAnswer.anonymous_id === anonymousId) {
            const previousCount = previousOwnCounts.current[updatedAnswer.id] ?? updatedAnswer.resonance_count
            if (updatedAnswer.resonance_count > previousCount) {
              setToast("Someone felt this too.")
            }
            previousOwnCounts.current[updatedAnswer.id] = updatedAnswer.resonance_count
          }
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [anonymousId, questionDate, supabase])

  useEffect(() => {
    if (!toast) return
    const timeout = window.setTimeout(() => setToast(""), 3200)
    return () => window.clearTimeout(timeout)
  }, [toast])

  const handlePost = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const trimmedAnswer = answerText.replace(/\s+/g, " ").trim()
    if (!trimmedAnswer || isPosting) return

    setIsPosting(true)
    const response = await fetch("/api/echoes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ anonymousId, answerText: trimmedAnswer }),
    })
    const data = await response.json()
    setIsPosting(false)

    if (!response.ok) {
      setToast(data.error || "Your Echo could not be posted.")
      return
    }

    setAnswerText("")
    setPostedAnswer(data.answer)
    setAnswers((current) => {
      if (current.some((answer) => answer.id === data.answer.id)) return current
      return [data.answer, ...current].slice(0, 80)
    })
  }

  const handleResonate = async (answer: EchoAnswer) => {
    if (answer.anonymous_id === anonymousId) return

    setAnswers((current) =>
      current.map((item) =>
        item.id === answer.id ? { ...item, resonance_count: item.resonance_count + 1 } : item
      )
    )

    const response = await fetch("/api/echoes/resonate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ answerId: answer.id, anonymousId }),
    })

    if (!response.ok && response.status !== 409) {
      const data = await response.json()
      setToast(data.error || "Resonance did not save.")
      loadEchoes()
    }
  }

  return (
    <main className="min-h-screen overflow-hidden bg-background text-foreground">
      <div className="pointer-events-none fixed inset-0 bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.08),transparent_32rem)]" />

      <header className="sticky top-0 z-40 border-b border-border bg-background/90 backdrop-blur-md">
        <div className="container mx-auto flex items-center justify-between px-4 py-4">
          <Link
            href="/"
            className="flex h-10 w-10 items-center justify-center rounded-full border border-border bg-secondary/50 text-muted-foreground transition hover:text-foreground"
            aria-label="Return home"
          >
            <ArrowLeft className="h-4 w-4" aria-hidden="true" />
          </Link>
          <span className="text-sm font-medium tracking-[0.3em] text-muted-foreground">ECHOES</span>
          <Link href="/twin" className="text-sm text-muted-foreground transition hover:text-foreground">
            Twin
          </Link>
        </div>
      </header>

      <section className="container relative z-10 mx-auto px-4 py-10 sm:py-14">
        <div className="mx-auto max-w-3xl text-center">
          <p className="mb-4 text-xs uppercase tracking-[0.24em] text-muted-foreground">{questionDate || "Today"}</p>
          <h1 className="text-3xl font-light leading-tight text-foreground sm:text-5xl">
            {question || "What wants to be heard today?"}
          </h1>

          <form onSubmit={handlePost} className="mx-auto mt-8 flex max-w-2xl gap-2 rounded-2xl border border-border bg-card/60 p-2 shadow-[0_0_50px_rgba(255,255,255,0.04)]">
            <input
              value={answerText}
              onChange={(event) => setAnswerText(event.target.value)}
              maxLength={180}
              placeholder="Leave one anonymous line"
              className="min-w-0 flex-1 bg-transparent px-3 py-3 text-sm text-foreground outline-none placeholder:text-muted-foreground/60"
              aria-label="Anonymous Echo answer"
            />
            <button
              type="submit"
              disabled={!answerText.trim() || isPosting}
              className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-foreground text-background transition hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-40"
              aria-label="Post Echo"
            >
              {isPosting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
            </button>
          </form>
        </div>

        {postedAnswer && (
          <div className="mx-auto mt-8 max-w-3xl">
            <FindYourTwin sourceType="echo" sourceId={postedAnswer.id} textSeed={postedAnswer.answer_text} compact />
          </div>
        )}

        <div className="mx-auto mt-10 grid max-w-5xl gap-3 sm:grid-cols-2 lg:grid-cols-3">
          <AnimatePresence initial={false}>
            {isLoading ? (
              <div className="col-span-full flex items-center justify-center gap-3 py-16 text-sm text-muted-foreground">
                <Loader2 className="h-4 w-4 animate-spin" />
                Gathering today&apos;s Echoes
              </div>
            ) : (
              answers.map((answer, index) => (
                <motion.article
                  key={answer.id}
                  layout
                  initial={{ opacity: 0, y: 18, scale: 0.98 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.96 }}
                  transition={{ delay: Math.min(index * 0.025, 0.3) }}
                  className="flex min-h-36 flex-col justify-between rounded-2xl border border-border/80 bg-card/70 p-5 shadow-[0_0_26px_rgba(255,255,255,0.035)]"
                >
                  <p className="text-base font-light leading-relaxed text-foreground">{answer.answer_text}</p>
                  <button
                    onClick={() => handleResonate(answer)}
                    disabled={answer.anonymous_id === anonymousId}
                    className="mt-6 inline-flex w-fit items-center gap-2 rounded-full border border-border bg-background/60 px-3 py-2 text-sm text-muted-foreground transition hover:border-rose-200/40 hover:text-rose-100 disabled:cursor-default disabled:opacity-70"
                    aria-label="Resonate with this Echo"
                  >
                    <Heart className="h-4 w-4" aria-hidden="true" />
                    <span>{answer.resonance_count || 0}</span>
                  </button>
                </motion.article>
              ))
            )}
          </AnimatePresence>
        </div>
      </section>

      <AnimatePresence>
        {toast && (
          <motion.div
            initial={{ opacity: 0, y: 18 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 18 }}
            className="fixed bottom-6 left-1/2 z-50 -translate-x-1/2 rounded-full border border-border bg-card px-5 py-3 text-sm text-foreground shadow-2xl"
            role="status"
          >
            {toast}
          </motion.div>
        )}
      </AnimatePresence>
    </main>
  )
}

